create table public.supplier_risks(id uuid primary key default gen_random_uuid(),supplier_id uuid not null references public.suppliers(id) on delete restrict,organization_id uuid not null references public.organizations(id) on delete restrict,title text not null check(length(trim(title)) between 5 and 240),description text not null check(length(trim(description)) between 10 and 5000),impact text not null check(impact in('LOW','MEDIUM','HIGH','CRITICAL')),likelihood text not null check(likelihood in('LOW','MEDIUM','HIGH')),operational_dependency text not null check(operational_dependency in('LOW','MEDIUM','HIGH','CRITICAL')),alternative_supplier text,contingency_plan text,active boolean not null default true,created_at timestamptz not null default now(),created_by uuid references public.user_profiles(id) on delete set null,updated_at timestamptz not null default now(),updated_by uuid references public.user_profiles(id) on delete set null);
create trigger supplier_risks_updated before update on public.supplier_risks for each row execute function public.set_updated_at();
create index supplier_risks_org_active_idx on public.supplier_risks(organization_id,active,impact);
alter table public.supplier_risks enable row level security;
create policy "members read supplier risks" on public.supplier_risks for select to authenticated using(public.is_organization_member(organization_id));
create policy "managers manage supplier risks" on public.supplier_risks for all to authenticated using(public.has_organization_role(organization_id,array['SUPER_ADMIN','ORG_ADMIN','MANAGER']::public.platform_role[])) with check(public.has_organization_role(organization_id,array['SUPER_ADMIN','ORG_ADMIN','MANAGER']::public.platform_role[]));
